proc-info:
cat > /home/learner/aso/f33/proc-info.sh <<'SOLUCION'
#!/bin/bash
[ $# -eq 1 ] || { echo 'uso: proc-info.sh PID' >&2; exit 1; }
[[ $1 =~ ^[0-9]+$ ]] || { echo 'error: el PID debe ser un número' >&2; exit 2; }
[ -d "/proc/$1" ] || { echo "error: no existe el proceso $1" >&2; exit 3; }
while IFS=$'\t' read -r clave valor resto; do
    case $clave in
        Name:) echo "Nombre: $valor" ;;
        State:) echo "Estado: $valor" ;;
        PPid:) echo "Padre: $valor" ;;
        Uid:) echo "UID real: $valor" ;;
    esac
done < "/proc/$1/status"
orden=$(tr '\0' ' ' < "/proc/$1/cmdline")
echo "Orden: ${orden% }"
SOLUCION
chmod 755 /home/learner/aso/f33/proc-info.sh
chown learner:learner /home/learner/aso/f33/proc-info.sh
